/* ── Comment Markdown ──────────────────────────────────────── */
/* Lightweight prose styling for the short Markdown rendered in
   margin comments, persona notes, and suggestion rationales.
   Scoped via `.comment-markdown` so it never bleeds into the
   editor's prose or manuscript paste. */
.comment-markdown {
  /* Honor the host's line-height / colour set inline; only add
     the bits Markdown needs. */
}

.comment-markdown p {
  margin: 0;
  /* marked emits one paragraph per blank-line block. Soft breaks
     inside a paragraph are <br>, which contributes its own space;
     trim the trailing gap so multiple paragraphs don't double up
     when the host uses `space-y-*` layout. */
}
.comment-markdown p + p {
  margin-top: 0.45em;
}

.comment-markdown ul,
.comment-markdown ol {
  margin: 0.4em 0;
  padding-left: 1.25em;
  list-style-position: outside;
}
.comment-markdown ul {
  list-style-type: disc;
}
.comment-markdown ol {
  list-style-type: decimal;
}
.comment-markdown li {
  margin: 0.15em 0;
}
.comment-markdown li > p {
  display: inline;
  margin: 0;
}

.comment-markdown strong {
  font-weight: 600;
  color: var(--color-ink);
}
.comment-markdown em {
  font-style: italic;
}
.comment-markdown code {
  font-family: var(--font-typewriter);
  font-size: 0.92em;
  padding: 0 0.25em;
  border-radius: 1px;
  background: var(--color-paper-3);
  color: var(--color-ink);
}
.comment-markdown a {
  color: var(--color-cobalt);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}
.comment-markdown a:hover {
  color: var(--color-vermilion);
}

/* ── The editorial board panels ────────────────────────────── */
/* The board shares the viewport shell with the drawer and main column. It
   consumes real horizontal space without inheriting the masthead offset. */
.editorial-overlay {
  position: relative;
  inset: auto;
  z-index: var(--z-overlay);
  flex: 0 0 auto;
  align-self: stretch;
  width: min(29rem, calc(100% - 3rem));
   the name, and a right rail for the category stamp — so the card
   uses both its edges instead of stacking everything against the
   left one. And the foot is a real foot: divided by a hairline,
   with the actions the writer takes on the left and the ones they
   take on the card itself pushed to the right. */
.desk-card {
  --card-accent: var(--color-paper-3);
  --card-pad-x: 0.9rem;
  --card-pad-y: 0.8rem;
  /* The foot's keys carry their own padding so they have a hit area.
     This pulls the row back so its text still sits flush with the
     card's left margin. */
  --card-key-inset: 0.45rem;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: var(--card-pad-y) var(--card-pad-x);
  border-radius: 2px;
}

/* ── Masthead ── */
.desk-card__head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: start;
  column-gap: 0.55rem;
  row-gap: 0.1rem;
}
/* The gutter. Spans both masthead rows so the portrait is a margin
   the name and byline hang off, not another item in the queue. */
.desk-card__mark {
  grid-column: 1;
  grid-row: 1 / span 2;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  align-self: center;
}
.desk-card__name {
  grid-column: 2;
  grid-row: 1;
  min-width: 0;
  margin: 0;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 0.9375rem;
  line-height: 1.25;
  color: var(--color-ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* A title long enough that clipping it loses the point — a source's
   full name, a criterion. Wraps instead of truncating. */
.desk-card__name--wrap {
  white-space: normal;
  overflow: visible;
  line-height: 1.3;
}

/* The right rail — one short word saying what kind of card this is.
   Aligned to the card's right margin so the head has two anchors. */
.desk-card__stamp {
  grid-column: 3;
  grid-row: 1;
  justify-self: end;
  /* Aligned to the name's first line, not to the middle of however many
     lines it runs to — a stamp floating beside line two of a wrapped
     title is the tell that nothing was laid out on purpose. */
  align-self: start;
  margin-top: 0.05rem;
  flex-shrink: 0;
  padding: 0.05rem 0.35rem;
  border: 1px solid color-mix(in srgb, var(--card-accent) 55%, transparent);
  border-radius: 2px;
  font-family: var(--font-typewriter);
  font-size: 0.625rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  line-height: 1.5;
  color: var(--card-accent);
  white-space: nowrap;
}
/* Understated variant for a stamp that is a fact, not a category. */
.desk-card__stamp--quiet {
  border-color: transparent;
  color: var(--color-ink-muted);
  padding-inline: 0;
}
/* Second masthead line: role, time, provenance — and, pushed right,
   the utilities that belong to the card rather than the note. */
.desk-card__byline {
  grid-column: 2 / -1;
  grid-row: 2;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  font-family: var(--font-typewriter);
  font-size: 0.6875rem;
  letter-spacing: 0.1em;
  color: var(--color-ink-muted);
}
.desk-card__byline > .desk-card__tools {
  margin-left: auto;
}
.desk-card__tools {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  flex-shrink: 0;
}
/* A byline that holds a disclosure rather than a row of facts —
   same slot, same ink, but block flow so <details> still works. */
.desk-card__aside {
  grid-column: 2 / -1;
  grid-row: 2;
  min-width: 0;
  font-family: var(--font-typewriter);
  font-size: 0.6875rem;
  letter-spacing: 0.1em;
  color: var(--color-ink-muted);
}

/* ── The anchored passage ──
   A quotation from the manuscript, given the hanging rule it has
   earned rather than being run in as another line of small print. */
.desk-card__quote {
  margin: 0;
  padding: 0.1rem 0 0.1rem 0.6rem;
  border-left: 2px solid color-mix(in srgb, var(--card-accent) 70%, transparent);
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--color-ink-muted);
  transition: color 0.16s ease;
}
.desk-card__quote--action {
  cursor: pointer;
}
.desk-card__quote--action:hover {
  color: var(--color-ink);
}

/* Quotations inside a note. A resolved one leads to its passage; one that
   could not be placed stays plain text with a dotted rule and says why. */
.comment-markdown .quote-link {
  cursor: pointer;
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, currentColor 45%, transparent);
  text-underline-offset: 0.18em;
}
.comment-markdown .quote-link:hover,
.comment-markdown .quote-link:focus-visible {
  text-decoration-color: currentColor;
  outline: none;
}
.comment-markdown .quote-unresolved {
  text-decoration: underline dotted;
  text-decoration-color: color-mix(in srgb, currentColor 35%, transparent);
  text-underline-offset: 0.18em;
  cursor: help;
}

/* ── The note ──
   Full measure. In a 340px panel the reading column is scarce, so
   the body does not pay for the gutter the masthead spends. */
.desk-card__body {
  font-family: var(--font-serif);
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--color-ink-light);
}
.desk-card__body--clamped {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  overflow: hidden;
  cursor: pointer;
}
/* A run of monospaced detail — a URL, a raw citation string. */
.desk-card__detail {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  line-height: 1.45;
  color: var(--color-ink-muted);
  overflow-wrap: anywhere;
}

/* ── The foot ──
   A hairline, then the actions. `__foot-end` claims the right edge,
   which is the whole point: the card stops being one left-aligned
   pile and becomes a thing with two margins.

   The outer row never wraps. If it did, the right cluster — which is
   usually the quiet hover-revealed one — would drop onto a line of
   its own and, being invisible at rest, read as a hole in the bottom
   of the card. Only the left cluster wraps, inside itself. */
.desk-card__foot {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.25rem;
  padding-top: 0.5rem;
  border-top: 1px solid
    color-mix(in srgb, var(--color-paper-3) 65%, transparent);
}
/* The keys carry padding for a hit area; the clusters pull that back
   so the row's text still sits flush with the card's margins and the
   hairline above it. */
.desk-card__foot-start {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.1rem 0.15rem;
  min-width: 0;
  margin-inline-start: calc(var(--card-key-inset) * -1);
}
.desk-card__foot-end {
  display: flex;
  align-items: center;
  gap: 0.1rem;
  flex-shrink: 0;
  margin-left: auto;
  margin-inline-end: calc(var(--card-key-inset) * -1);
}

/* ── Controls block ──
   For cards that are settings rather than notes. The selects sit in a
   responsive grid instead of a flex row, so a narrow column stacks them
   at full width rather than crushing two pickers into one line. Each
   field carries its own label, because an unlabelled select in a row of
   selects is a guess. */
.desk-card__controls {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(10.5rem, 1fr));
  gap: 0.5rem 0.75rem;
  padding: 0.6rem 0.7rem;
  border: 1px solid color-mix(in srgb, var(--color-paper-3) 70%, transparent);
  border-radius: 2px;
  background: color-mix(in srgb, var(--color-paper-2) 45%, transparent);
}
.card-field {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

/* Chrome that only matters once the writer is looking at this card.
