async function conveneQuietly(input: {
  draftText: string;
  newMaterial: string;
  trajectory: string;
  brief: ProjectBrief | null;
  client: ConvexClient | null;
  personas: Persona[];
}): Promise<QuietResponse[]> {
  const settings = await getCachedAiSettings();
  const writerProfile = (await loadWriterSettingsFromIdb()).profile;

  if (hasConfiguredAiProvider(settings)) {
    const results = await Promise.all(
      input.personas.map(async (p) => {
        const reviewer = input.client
          ? createEditorialNoteReviewer(
              (request) =>
                askJudgement(input.client, {
                  ...request,
                  state: Object.fromEntries(
                    Object.entries(request.state).map(([key, value]) => [
                      key,
                      typeof value === "string" ? value : JSON.stringify(value),
                    ]),
                  ),
                }),
              {
                draft: input.draftText,
                brief: input.brief,
                persona: p,
                profile: writerProfile,
                operation: "feedback",
              },
            )
          : undefined;
        const res = await runClientAgent(
          "persona-feedback",
          {
            persona: toAgentPersona(p),
            brief: input.brief,
            draftText: input.draftText,
            writerProfile,
            newMaterial: input.newMaterial,
            trajectory: input.trajectory,
            instruction: "feedback" as const,
          },
          settings,
          undefined,
          reviewer
            ? {
                review: reviewer,
              }
            : undefined,
        );
        if (!res || !res.text.trim() || res.provider === "local") return null;
        const note: QuietResponse = {
          personaId: p.id,
          text: res.text,
          type: res.type,
          provider: res.provider,
          anchor: res.anchor,
        };
        return note;
      }),
    );
    return results.filter((r): r is QuietResponse => r !== null);
  }

  if (!input.client) return [];
  const result = (await input.client.action(api.agents.conveneRoom, {
    responseLocale: currentModelLocale(),
    personas: input.personas.map(toAgentPersona),
    brief: input.brief ?? null,
    draftText: input.draftText,
    writerProfile,
    newMaterial: input.newMaterial,
    trajectory: input.trajectory,
  })) as QuietResponse[];
  return result.filter((r) => r.text.trim() && r.provider !== "local");
}

