.comment-markdown a:hover {
  color: var(--color-vermilion);
}
.comment-markdown del {
  text-decoration-thickness: 1px;
  color: var(--color-ink-muted);
}
/* Notes are short, so headings are run-in labels, not page titles: one
   step up from the body and set in the display face, never larger. */
.comment-markdown :is(h1, h2, h3, h4, h5, h6) {
  margin: 0.7em 0 0.25em;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.04em;
  line-height: 1.3;
  color: var(--color-ink);
  text-wrap: balance;
}
.comment-markdown :is(h4, h5, h6) {
  font-size: 1em;
}
.comment-markdown > :first-child {
  margin-top: 0;
}
.comment-markdown > :last-child {
  margin-bottom: 0;
}
.comment-markdown :is(ul, ol) :is(ul, ol) {
  margin: 0.15em 0;
}
.comment-markdown :is(blockquote, pre, table, hr) {
  margin: 0.55em 0;
}
.comment-markdown blockquote {
  padding-left: 0.65em;
  border-left: 2px solid
    color-mix(in srgb, var(--card-accent, var(--color-paper-3)) 60%, transparent);
  font-style: italic;
  color: var(--color-ink-light);
}
.comment-markdown hr {
  height: 0;
  border: 0;
  border-top: 1px solid var(--color-paper-3);
}
.comment-markdown pre {
  max-width: 100%;
  overflow-x: auto;
  padding: 0.45em 0.6em;
  border-radius: 2px;
  background: var(--color-paper-3);
  line-height: 1.45;
}
.comment-markdown pre code {
  padding: 0;
  background: none;
  white-space: pre;
}
/* A table scrolls inside its own box rather than widening the card. */
.comment-markdown table {
  display: block;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  font-size: 0.92em;
}
.comment-markdown :is(th, td) {
  padding: 0.25em 0.75em 0.25em 0;
  border-bottom: 1px solid
    color-mix(in srgb, var(--color-paper-3) 80%, transparent);
  text-align: left;
  vertical-align: top;
}
.comment-markdown th {
  font-family: var(--font-typewriter);
  font-weight: 400;
  font-size: 0.85em;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}

