  text-align: left;
  cursor: pointer;
}
.note-sheet__quote-text {
  font: italic 400 0.9375rem/1.55 var(--font-serif);
  color: var(--color-ink-light);
  overflow-wrap: anywhere;
}
.note-sheet__quote-go {
  font-family: var(--font-typewriter);
  font-size: 0.625rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.note-sheet__quote:hover .note-sheet__quote-text,
.note-sheet__quote:focus-visible .note-sheet__quote-text {
  color: var(--color-ink);
}
.note-sheet__quote:hover .note-sheet__quote-go,
.note-sheet__quote:focus-visible .note-sheet__quote-go {
  color: var(--color-vermilion);
}
.note-sheet__quote:focus-visible {
  outline: 2px solid var(--color-vermilion);
  outline-offset: 2px;
}
.note-sheet__body {
  max-width: 65ch;
  font-family: var(--font-serif);
  font-size: 1rem;
  line-height: 1.65;
  color: var(--color-ink);
}
.note-sheet__foot,
.note-sheet__reply {
  flex-shrink: 0;
  padding: 0.6rem 1.5rem 0.75rem;
  border-top: 1px solid
    color-mix(in srgb, var(--color-paper-3) 70%, transparent);
}
@media (max-width: 30rem) {
  .note-sheet {
    width: 100vw;
    max-height: 100dvh;
    margin: auto 0 0;
    border-radius: 3px 3px 0 0;
  }
  .note-sheet__head {
    padding: 1rem 0.75rem 0.85rem 1rem;
    gap: 0.65rem;
  }
  .note-sheet__scroll,
  .note-sheet__foot,
  .note-sheet__reply {
    padding-inline: 1rem;
  }
}
@media (prefers-reduced-motion: no-preference) {
  .note-sheet[open] {
    animation: noteSheetIn 0.18s ease-out;
  }
  @keyframes noteSheetIn {
    from {
      opacity: 0;
      transform: translateY(6px);
    }
  }
}
@media (prefers-reduced-motion: reduce) {
  .note-card--passing,
  .note-card__open {
    transition: none;
  }
}

